close all; clear all; clc;load("funcaotransferencia2.mat","tf1")G = tf(tf1);figure;step(G)%Cs = Kp + Ki/s + Kd * s;Kp = 4.658;Ki = 0.01131;Kd = 0;numC = [Kd Kp Ki];denC = [1 0];C = tf(numC, denC);CGs = C * G;T = feedback(CGs, 1);figure;step(T);%sisotool(G,C)% Outras Versões (tempo de acomodação mais rápido)% Só precisa validar a questão da saturação realKp2 = 7.1323; %5.2649;Ki2 = 7.1323 * 0.002762; %5.2649 * 0.002762;Kd2 = 0;numC2 = [Kd2 Kp2 Ki2];denC2 = [1 0];C2 = tf(numC2, denC2);CGs2 = C2 * G;T2 = feedback(CGs2, 1);figure;step(T2);